from collections import deque
R=C=30
D4=[(-1,0),(1,0),(0,-1),(0,1)]
D8=[(i,j) for i in (-1,0,1) for j in (-1,0,1) if (i,j)!=(0,0)]
# 0 components
zid=[[-1]*C for _ in range(R)]; zcomps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==0 and zid[r][c]<0:
   k=len(zcomps); q=[(r,c)]; zid[r][c]=k; cells=[]
   for y,x in q:
    cells.append((y,x))
    for dy,dx in D4:
     yy,xx=y+dy,x+dx
     if 0<=yy<R and 0<=xx<C and grid[yy][xx]==0 and zid[yy][xx]<0:
      zid[yy][xx]=k;q.append((yy,xx))
   zcomps.append(cells)
# identify exterior / enclosed regions
outside=set()
for k,cells in enumerate(zcomps):
 if any(y in (0,R-1) or x in (0,C-1) for y,x in cells): outside.add(k)
# one component labels 4-connectivity
lab=[[-1]*C for _ in range(R)]; comps=[]
for r in range(R):
 for c in range(C):
  if grid[r][c]==1 and lab[r][c]<0:
   k=len(comps); q=[(r,c)];lab[r][c]=k;cells=[]
   for y,x in q:
    cells.append((y,x))
    for dy,dx in D4:
     yy,xx=y+dy,x+dx
     if 0<=yy<R and 0<=xx<C and grid[yy][xx]==1 and lab[yy][xx]<0:lab[yy][xx]=k;q.append((yy,xx))
   comps.append(cells)
comp_holes={}
for k,cells in enumerate(zcomps):
 if k in outside: continue
 adj={lab[y+dy][x+dx] for y,x in cells for dy,dx in D4 if 0<=y+dy<R and 0<=x+dx<C and lab[y+dy][x+dx]>=0}
 for a in adj:comp_holes.setdefault(a,[]).append(k)
[(i,len(v), (min(y for y,x in v),max(y for y,x in v),min(x for y,x in v),max(x for y,x in v)),len(comp_holes.get(i,[]))) for i,v in enumerate(comps)],[(k,len(zcomps[k]),(min(y for y,x in zcomps[k]),max(y for y,x in zcomps[k]),min(x for y,x in zcomps[k]),max(x for y,x in zcomps[k]))) for k in range(len(zcomps)) if k not in outside]

out=[row[:] for row in grid]
closed=set(comp_holes)
# Interior boundary cells get 3 if 8-neighbor to component boundary.
for ci, holes in comp_holes.items():
 for hk in holes:
  for y,x in zcomps[hk]:
   if any(0<=y+dy<R and 0<=x+dx<C and lab[y+dy][x+dx]==ci for dy,dx in D8):out[y][x]=3
# Exterior 8-neighbor halo for each closed 1 component.
for ci in closed:
 for y,x in comps[ci]:
  for dy,dx in D8:
   yy,xx=y+dy,x+dx
   if 0<=yy<R and 0<=xx<C and grid[yy][xx]==0 and zid[yy][xx] in outside and out[yy][xx]==0:out[yy][xx]=2
print('closed comps',closed)
for row in out:print(' '.join(map(str,row)))
